import React from "react";
var c = 0;
var s = [];
function Dyna(p) {
  const [hove, sethover] = React.useState(false);
  const [check, setcheck] = React.useState(false);
  function ddo() {
    sethover(true);
  }
  function unddo() {
    sethover(false);
  }

  var g = p.li;

  function style(event) {
    var h = p.tym - 1;
    var l = g.length;
    console.log(p.li);
    for (var w = 0; w < l; w++) {
      if (w !== h) {
        s.push(p.li[w]);
      }
    }
    p.ff(s);
    s = [];

    console.log(s);
    setcheck(false);
  }

  c++;
  return (
    <div className="row">
      <div
        className="col-lg-6 col-md-12"
        id={p.tym}
        onMouseOver={ddo}
        onMouseOut={unddo}
      >
        {p.lll + " -"}
        <button className="de" onClick={style}>
          {" "}
          Delete the task
        </button>{" "}
        {hove ? (
          <div>
            <p>created time {p.llll}</p>
          </div>
        ) : null}
      </div>
    </div>
  );
}
export default Dyna;
export { s };
